import { createPost } from './actions';

// Example function to fetch posts with cache tags
async function getPosts() {
  // This would be your actual data fetching logic
  // Using fetch with next.tags to add cache tags
  const res = await fetch('https://api.example.com/posts', {
    next: { tags: ['posts'] }
  });

  // For demo purposes, return mock data if fetch fails
  if (!res.ok) {
    return [
      { id: 1, title: 'First Post', content: 'This is the first post', createdAt: new Date().toISOString() }
    ];
  }

  return res.json();
}

export default async function Home() {
  const posts = await getPosts();

  return (
    <main style={{ padding: '2rem', maxWidth: '800px', margin: '0 auto' }}>
      <h1>Posts</h1>

      <section style={{ marginBottom: '2rem', padding: '1rem', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h2>Create New Post</h2>
        <form action={createPost}>
          <div style={{ marginBottom: '1rem' }}>
            <label htmlFor="title" style={{ display: 'block', marginBottom: '0.5rem' }}>
              Title:
            </label>
            <input
              type="text"
              id="title"
              name="title"
              required
              style={{ width: '100%', padding: '0.5rem', fontSize: '1rem' }}
            />
          </div>

          <div style={{ marginBottom: '1rem' }}>
            <label htmlFor="content" style={{ display: 'block', marginBottom: '0.5rem' }}>
              Content:
            </label>
            <textarea
              id="content"
              name="content"
              required
              rows={4}
              style={{ width: '100%', padding: '0.5rem', fontSize: '1rem' }}
            />
          </div>

          <button
            type="submit"
            style={{
              padding: '0.75rem 1.5rem',
              fontSize: '1rem',
              backgroundColor: '#0070f3',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            Create Post
          </button>
        </form>
      </section>

      <section>
        <h2>All Posts</h2>
        <ul style={{ listStyle: 'none', padding: 0 }}>
          {posts.map((post: any) => (
            <li key={post.id} style={{ marginBottom: '1rem', padding: '1rem', border: '1px solid #eee', borderRadius: '4px' }}>
              <h3>{post.title}</h3>
              <p>{post.content}</p>
              <small style={{ color: '#666' }}>
                {new Date(post.createdAt).toLocaleString()}
              </small>
            </li>
          ))}
        </ul>
      </section>
    </main>
  );
}

